        },
        {
          "find": "BATCH_SIZE    = int(os.environ.get(\"NEXTITNET_BATCH\", \"128\"))",
          "replace": "BATCH_SIZE    = int(os.environ.get(\"NEXTITNET_BATCH\", \"256\"))"
        }
      ]
    }
  ],
  "change_summary": "Jointly increase batch size and learning rate for all four independent NextItNet category models. Predictor and checkpoint shapes remain unchanged."
